#endif

#if USE_COLOR && USE_TEXTURE
    float alpha = Ambient.a * BlendIntensity;

    fragColor.rgb = textureColor.rgb * Ambient.rgb * alpha;
    fragColor.a   = textureColor.a * alpha;

#elif USE_COLOR
    fragColor = Ambient * BlendIntensity;

#elif USE_TEXTURE
