        { 0, 1, 2, 3 },
        // Right.
        { 5, 0, 3, 4 },
        // Back.
        { 6, 5, 4, 7 },
        // Left.
        { 1, 6, 7, 2 },
        // Top.
        { 5, 6, 1, 0 },
        // Bottom.
        { 3, 2, 7, 4 }
    };

    // Define normals for each face.
    const Vector3 faceNormals[] = {
        Vector3(0.0f, 0.0f, 1.0f),
        Vector3(1.0f, 0.0f, 0.0f),
        Vector3(0.0f, 0.0f, -1.0f),
        Vector3(-1.0f, 0.0f, 0.0f),
        Vector3(0.0f, 1.0f, 0.0f),
